## Technical details

```typescript
type PricingTablePlanKey = string;

interface PricingTablePlan {
  key: PricingTablePlanKey;
  name: string;
  ctaLink: string;
}

interface PricingTableRowValue {
  title?: string;
  description?: string;
  /** Renders the title as rainbow text */
  isHighlight?: boolean;
  linkText?: string;
  linkHref?: string;
  /** Each boolean renders a feature-icon. true indicates that the feature is included, false indicates that it is not. */
  subFeatures?: boolean[];
}

interface PricingTableRow {
  title: string;
  /** If set, the whole cell is a link */
  titleHref?: string;
  /** Rendered below title */
  description: string;
  /** Each string is rendered as a single text line to indicate sub-features */
  subFeatures?: string[];
  /** Indicate that all values are the same for all plans. Used for comparing differences between plans. */
  hasDifference: boolean;
  values: Record<PricingTablePlanKey, PricingTableRowValue>;
}

interface PricingTableSection {
  title: string;
  description: string;
  icon: string;
  anchor?: string;
  rows: PricingTableRow[];
}

interface PricingTable {
  plans: PricingTablePlan[];
  sections: PricingTableSection[];
}
```

